<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comparar productos | Xiaomi Store</title><link rel="stylesheet" href="styles.css"><style>body{font:15px Arial;background:#f5f5f5}.wrap{max-width:1100px;margin:35px auto;padding:18px}.table{overflow:auto;background:white;border-radius:14px;padding:15px}table{border-collapse:collapse;width:100%;min-width:550px}td,th{padding:14px;border-bottom:1px solid #eee;text-align:left}.error{color:#b71c1c}</style></head><body><main class="wrap"><a href="catalogo.php">← Catálogo</a><h1>Comparador de productos</h1><p>Compara hasta tres equipos antes de comprar.</p><div id="compareResult" class="table">Cargando comparación…</div></main><script type="module">const ids=JSON.parse(localStorage.getItem('xiaomi_compare')||'[]');const root=document.getElementById('compareResult');if(ids.length<2){root.textContent='Selecciona al menos dos productos desde el catálogo.';}else{try{const r=await fetch('backend/comparar_productos.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids})});const d=await r.json();if(!r.ok||!d.success)throw Error(d.message);const rows=[['Producto',p=>p.nombre],['Precio',p=>'S/ '+Number(p.precio).toFixed(2)],['Categoría',p=>p.categoria],['Marca',p=>p.marca||'—'],['Stock',p=>p.stock>0?'Disponible ('+p.stock+')':'Agotado'],['Garantía',p=>p.garantia||'Consultar'],['Descripción',p=>p.descripcion||'—']];root.innerHTML='<table><thead><tr><th>Característica</th>'+d.products.map(p=>'<th>'+String(p.nombre).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</th>').join('')+'</tr></thead><tbody>'+rows.map(([label,get])=>'<tr><th>'+label+'</th>'+d.products.map(p=>'<td>'+String(get(p)).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}catch(e){root.textContent=e.message||'No se pudo comparar.';}}</script></body></html>
